CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),revision INTEGER NOT NULL DEFAULT 0,claim TEXT,active INTEGER NOT NULL DEFAULT 0,proactive INTEGER NOT NULL DEFAULT 1,religion INTEGER NOT NULL DEFAULT 1,quiet_until INTEGER NOT NULL DEFAULT 0,goal INTEGER,monthly INTEGER,nudge_time TEXT NOT NULL DEFAULT '19:00',last_seen INTEGER NOT NULL DEFAULT 0,context TEXT NOT NULL DEFAULT '',last_cron INTEGER NOT NULL DEFAULT 0,telegram_pause INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO settings(id) VALUES(1);
CREATE TABLE IF NOT EXISTS wallets(wallet TEXT NOT NULL CHECK(wallet IN ('capital','pocket')),currency TEXT NOT NULL CHECK(currency IN ('RUB','AZN')),amount INTEGER NOT NULL DEFAULT 0 CHECK(amount>=0),initialized INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(wallet,currency));
INSERT OR IGNORE INTO wallets(wallet,currency) VALUES('capital','RUB'),('pocket','RUB'),('capital','AZN'),('pocket','AZN');
CREATE TABLE IF NOT EXISTS drafts(id TEXT PRIMARY KEY,payload TEXT NOT NULL,revision INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'ready',created_at INTEGER NOT NULL,expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY,kind TEXT NOT NULL,note TEXT NOT NULL,at INTEGER NOT NULL,reversal_of TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS entries(tx_id TEXT NOT NULL,wallet TEXT NOT NULL,currency TEXT NOT NULL,delta INTEGER NOT NULL,PRIMARY KEY(tx_id,wallet,currency));
CREATE INDEX IF NOT EXISTS entries_wallet ON entries(wallet,currency);
CREATE INDEX IF NOT EXISTS transactions_at ON transactions(at);
CREATE TABLE IF NOT EXISTS updates(id INTEGER PRIMARY KEY,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL,lease INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS updates_state ON updates(state,created_at);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY,payload TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',due INTEGER NOT NULL,lease INTEGER NOT NULL DEFAULT 0,message_id INTEGER,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS outbox_due ON outbox(state,due);
CREATE TABLE IF NOT EXISTS memory(id TEXT PRIMARY KEY,role TEXT NOT NULL,content TEXT NOT NULL,at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS memory_at ON memory(at);
CREATE TABLE IF NOT EXISTS locks(name TEXT PRIMARY KEY,token TEXT NOT NULL,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS budgets(day TEXT PRIMARY KEY,used INTEGER NOT NULL DEFAULT 0);
